const todoText = ref('')
const todoCountText = computed(() => todoCount.value === undefined ? DASH : String(todoCount.value))
onMounted(() => {
  fetchHome()
    .then(data => {
      news.value = (data.news ?? []).slice(0, 2)
      todoCount.value = data.todoCount
      todoText.value = data.todoText ?? ''
    })
    .catch(() => { news.value = [] })
})

/** 角色分流：roles[].roleKey 命中 wyqy/wyqygly 判 B 端；roles 空/未登录默认 G 端。 */
const isBEnd = ref(false)
function refreshRole() {
  const u = getLoginUser()
  const keys: string[] = [
    ...(u?.roles ?? []).map(r => String(r?.roleKey ?? '')),
    ...(u?.roleKeys ?? []).map(k => String(k ?? '')),
  ]
  isBEnd.value = keys.some(k => k === 'wyqy' || k === 'wyqygly')
}

