/** 统计指标响应式存储：累计（无 month）与当月（month=本地当前 yyyy-MM）。空/失败保持 undefined 显示「—」。 */
type HomeStats = { key?: NormalizedKey; benefit?: BenefitData; repair?: RepairData; sunshine?: SunshineOverview }
const stats = reactive<HomeStats>({})
const statsCur = reactive<HomeStats>({})
let statsReqId = 0
function currentMonth(): string {
  const n = new Date()
  return `${n.getFullYear()}-${String(n.getMonth() + 1).padStart(2, '0')}`
}
async function loadStats() {
  // G 端无有效权限区域时不请求（禁止空 parentDeptId=全市越权）；B 端不传 parentDeptId，由 @DataScope 按 token 控制。
  const deptId = isBEnd.value ? undefined : activeDeptId.value
  if (!isBEnd.value && (deptId === null || deptId === undefined || deptId === '')) {
    stats.key = stats.benefit = stats.repair = stats.sunshine = undefined
    statsCur.benefit = statsCur.repair = statsCur.sunshine = undefined
    return
  }
  const reqId = ++statsReqId
  const base = deptId === undefined ? {} : { parentDeptId: deptId }
  const month = currentMonth()
  // 切区域先清当月缓存，避免旧区域数据闪现。
  statsCur.benefit = statsCur.repair = statsCur.sunshine = undefined
  const [key, benefit, repair, sunshine, benefitCur, repairCur, sunshineCur] = await Promise.allSettled([
    getKeyData(base), getBenefitData(base), getRepairData(base), getSunshineOverview(base),
    getBenefitData({ ...base, month }), getRepairData({ ...base, month }), getSunshineOverview({ ...base, month }),
  ])
  // 竞态保护：区域/角色切换后旧请求迟到直接丢弃。
  if (reqId !== statsReqId) return
  if (key.status === 'fulfilled') stats.key = normalizeKeyData(key.value)
  if (benefit.status === 'fulfilled') stats.benefit = benefit.value
  if (repair.status === 'fulfilled') stats.repair = repair.value
  if (sunshine.status === 'fulfilled') stats.sunshine = sunshine.value
  statsCur.benefit = benefitCur.status === 'fulfilled' ? benefitCur.value : undefined
  statsCur.repair = repairCur.status === 'fulfilled' ? repairCur.value : undefined
  statsCur.sunshine = sunshineCur.status === 'fulfilled' ? sunshineCur.value : undefined
}

